 static void FinishScene(Scene scene){root=All<Transform>(scene).Single(t=>t.name==Marker);foreach(var t in All<Transform>(scene).Where(t=>t.name=="Desk and chair"&&t.position.y>15&&t.position.x>18&&t.position.x<28).ToArray())Hide(t);foreach(var t in root.GetComponentsInChildren<Transform>().Where(t=>t.name.StartsWith("Overturned_battered_factory_tool_cabinet-game")&&Mathf.Abs(t.localEulerAngles.z)<1).ToArray()){var rs=t.GetComponentsInChildren<Renderer>();var bounds=rs[0].bounds;foreach(var r in rs)bounds.Encapsulate(r.bounds);var centre=new Vector3(bounds.center.x,bounds.min.y,bounds.center.z);t.localRotation=Quaternion.Euler(0,t.localEulerAngles.y,82);bounds=rs[0].bounds;foreach(var r in rs)bounds.Encapsulate(r.bounds);t.position+=centre-new Vector3(bounds.center.x,bounds.min.y,bounds.center.z);EditorUtility.SetDirty(t);}
  SeatAndClear();RestoreHangingClothes(scene);if(root.Find("Alcove source lighting - low cost"))return;var fixtures=G("Alcove source lighting - low cost",root,Vector3.zero);var lights=new List<Light>();var tube=Mat("Frosted old fluorescent tubes",0x969e89);tube.SetColor("_EmissionColor",new Color(.24f,.27f,.20f));EditorUtility.SetDirty(tube);for(int i=0;i<3;i++){float y=7.6f+i*4;var g=G("F"+(i+2)+" rear work light",fixtures,new Vector3(22.0f,y+3.28f,5.0f));B("Battered reflector housing",g,Vector3.zero,new Vector3(1.35f,.07f,.26f),steel);foreach(float z in new[]{-.075f,.075f}){C("Frosted fluorescent tube",g,new Vector3(0,-.055f,z),.016f,1.17f,tube).localRotation=Quaternion.Euler(0,0,90);foreach(float x in new[]{-.60f,.60f})B("Tube end socket",g,new Vector3(x,-.05f,z),new Vector3(.06f,.06f,.05f),dark);}foreach(float x in new[]{-.50f,.50f})Rod("Conduit hanger",g,new Vector3(x,.03f,0),new Vector3(x,.32f,0),.012f,steel);var lt=G("Shadowless diffuse alcove lamp",g,new Vector3(0,-.16f,-.08f));var l=lt.gameObject.AddComponent<Light>();l.type=LightType.Spot;lt.localRotation=Quaternion.Euler(72,0,0);l.color=new Color(.81f,.84f,.72f);l.intensity=i==0?1.3f:1.65f;l.range=6.5f;l.spotAngle=128;l.innerSpotAngle=85;l.shadows=LightShadows.None;lights.Add(l);}
