 static void SeatAndClear(){if(root.Find("F2 seating support and clear foot space"))return;var area=root.Find("F2 rest and aid alcove - reused factory supplies");var children=area.Cast<Transform>().ToArray();var bench=children.Single(t=>t.name=="Workers slatted bench");bench.localPosition=new Vector3(23,0,3.15f);bench.localScale=new Vector3(1,1.263158f,1);var chair=children.Single(t=>t.name=="Overturned plywood chair");chair.localPosition+=new Vector3(-1,0,1.6f);var debris=children.Single(t=>t.name=="Splintered timber plaster chips and drag remnants");debris.localPosition=new Vector3(19.6f,0,3.1f);children.Single(t=>t.name=="Chipped enamel cup").localPosition=new Vector3(22.3f,0,5.75f);children.Single(t=>t.name=="Discarded typed supply record 1").localPosition=new Vector3(24,.01f,5.0f);var pot=children.Single(t=>t.name.StartsWith("Discarded_enamel_cooking_pot-game"));var rs=pot.GetComponentsInChildren<Renderer>();var bounds=rs[0].bounds;foreach(var r in rs)bounds.Encapsulate(r.bounds);pot.position+=area.TransformPoint(new Vector3(22.4f,0,6.13f))-new Vector3(bounds.center.x,bounds.min.y,bounds.center.z);G("F2 seating support and clear foot space",root,Vector3.zero);}
 public static string RepairSeating(){if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Stop play before authoring");Prepare();var previous=SceneManager.GetActiveScene();var scene=SceneManager.GetSceneByPath(ScenePath);bool opened=!scene.isLoaded;if(opened)scene=EditorSceneManager.OpenScene(ScenePath,OpenSceneMode.Additive);try{string backup="Backups/FactoryWorkerBase/BeforeSeatRepair-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".unity";EditorSceneManager.SaveScene(scene,backup,true);root=All<Transform>(scene).Single(t=>t.name==Marker);var npc=All<Transform>(scene).Single(t=>t.name=="Coaler cosplayer - resting on F2 bench");var npcState=npc.position+"|"+npc.rotation+"|"+npc.localScale;var doors=All<RecoilDoor>(scene).Select(d=>EditorJsonUtility.ToJson(d)).ToArray();var physics=All<Collider2D>(scene).Select(c=>c.GetInstanceID()+"|"+c.bounds+"|"+c.enabled).ToArray();SeatAndClear();var batch=root.Find("Combined native detail - source parts retained editable");if(batch)Object.DestroyImmediate(batch.gameObject);foreach(var f in root.GetComponentsInChildren<MeshFilter>().Where(f=>f.GetComponent<MeshRenderer>()&&!PrefabUtility.IsPartOfPrefabInstance(f)&&!f.GetComponentInParent<ReadableProp>()))f.GetComponent<MeshRenderer>().enabled=true;Batch(root);Physics2D.SyncTransforms();if(npcState!=npc.position+"|"+npc.rotation+"|"+npc.localScale)throw new Exception("NPC moved");if(!doors.SequenceEqual(All<RecoilDoor>(scene).Select(d=>EditorJsonUtility.ToJson(d))))throw new Exception("Door changed");if(!physics.SequenceEqual(All<Collider2D>(scene).Select(c=>c.GetInstanceID()+"|"+c.bounds+"|"+c.enabled)))throw new Exception("Collision changed");EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();string report="Moved the slatted bench under the seated worker: seat top Y8.20, below upper-leg bones Y8.31; worker transform and pose unchanged. Moved debris to left edge, fallen chair and cooking ware to rear, paper under aid table. Regenerated combined visuals so old debris locations are removed. Original collision and door components unchanged. Backup="+backup;File.WriteAllText("output/factory-worker-base/seating-repair.txt",report);return report;}finally{if(opened)EditorSceneManager.CloseScene(scene,true);SceneManager.SetActiveScene(previous);}}
 static void Batch(Transform parent){var filters=parent.GetComponentsInChildren<MeshFilter>().Where(f=>f.GetComponent<MeshRenderer>()&&f.GetComponent<MeshRenderer>().enabled&&!PrefabUtility.IsPartOfPrefabInstance(f)&&!f.GetComponent<ReadableProp>()&&!f.GetComponentInParent<ReadableProp>()).ToArray();var groups=filters.GroupBy(f=>f.GetComponent<MeshRenderer>().sharedMaterial);var target=G("Combined native detail - source parts retained editable",parent,Vector3.zero);foreach(var group in groups){var list=group.ToArray();if(list.Length<3)continue;var mesh=new Mesh{name="Combined "+group.Key.name,indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};mesh.CombineMeshes(list.Select(f=>new CombineInstance{mesh=f.sharedMesh,transform=parent.worldToLocalMatrix*f.transform.localToWorldMatrix}).ToArray(),true,true);string path=Folder+"/Models/Combined "+group.Key.name+".asset";var saved=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(saved){EditorUtility.CopySerialized(mesh,saved);Object.DestroyImmediate(mesh);mesh=saved;}else AssetDatabase.CreateAsset(mesh,path);var t=G("Combined "+group.Key.name,target,Vector3.zero);t.gameObject.AddComponent<MeshFilter>().sharedMesh=mesh;t.gameObject.AddComponent<MeshRenderer>().sharedMaterial=group.Key;foreach(var f in list)f.GetComponent<MeshRenderer>().enabled=false;}}
 public static string Capture(){if(EditorApplication.isPlayingOrWillChangePlaymode)return "Stop play before capture";var prev=SceneManager.GetActiveScene();var scene=SceneManager.GetSceneByPath(ScenePath);bool opened=!scene.isLoaded;if(opened)scene=EditorSceneManager.OpenScene(ScenePath,OpenSceneMode.Additive);var rs=Object.FindObjectsOfType<Renderer>(true).Where(r=>r.enabled&&r.gameObject.scene!=scene).ToArray();var ls=Object.FindObjectsOfType<Light>(true).Where(l=>l.enabled&&l.gameObject.scene!=scene).ToArray();GameObject cam=null;try{foreach(var r in rs)r.enabled=false;foreach(var l in ls)l.enabled=false;SceneManager.SetActiveScene(scene);foreach(var w in All<Recoil3DWorld>(scene))w.ApplyAtmosphere();foreach(var look in All<WarehouseAtmosphereTest>(scene))look.ApplyLook();cam=new GameObject("Temporary worker refuge review camera");SceneManager.MoveGameObjectToScene(cam,scene);var camera=cam.AddComponent<Camera>();camera.nearClipPlane=.1f;camera.farClipPlane=100;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.025f,.03f,.03f);camera.fieldOfView=44;for(int i=0;i<3;i++){float y=7.6f+i*4;camera.transform.position=new Vector3(22,y+2,-4);camera.transform.LookAt(new Vector3(22,y+1.35f,4.8f));Shot(camera,"Workers-refuge-F"+(i+2));}camera.transform.position=new Vector3(10.6f,9.6f,-10);camera.transform.LookAt(new Vector3(10.6f,9.2f,2.2f));Shot(camera,"Workers-corridor-F2");camera.fieldOfView=38;camera.transform.position=new Vector3(23,9.0f,-.8f);camera.transform.LookAt(new Vector3(23,8.4f,3.15f));Shot(camera,"Seated-worker-clear-floor");camera.transform.position=new Vector3(20.7f,9.0f,-.5f);camera.transform.LookAt(new Vector3(23,8.35f,3.15f));Shot(camera,"Seated-worker-seat-contact");return "Captured alcoves, corridor and seated worker front/angled contact views using scene lighting; no scene saved during capture";}finally{if(cam)Object.DestroyImmediate(cam);foreach(var r in rs)if(r)r.enabled=true;foreach(var l in ls)if(l)l.enabled=true;if(opened)EditorSceneManager.CloseScene(scene,true);SceneManager.SetActiveScene(prev);foreach(var w in All<Recoil3DWorld>(prev))w.ApplyAtmosphere();foreach(var look in All<WarehouseAtmosphereTest>(prev))look.ApplyLook();}}
 static void Shot(Camera camera,string name){typeof(FactoryRoofStairHeadPass).GetMethod("Shot",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic).Invoke(null,new object[]{camera,name});Directory.CreateDirectory("Captures/FactoryWorkerBase");File.Copy("Captures/FactoryRoofStairHead/"+name+".png","Captures/FactoryWorkerBase/"+name+".png",true);}
